const names={
 sideIRRetainedLead:['背面までのセンサーケーブル','Sensor cable to the rear','Kabel senzoru k zadní části','Sensorkabel zur Rückseite'],
 sideIROldBoard:['交換前のIR基板','Original IR board','Původní IR deska','Bisherige IR-Platine'],sideIRNewBoard:['交換用IR基板','Replacement IR board','Náhradní IR deska','Ersatz-IR-Platine'],sideIRM2:['基板固定用M2x8','Board fixing M2x8','Upevňovací M2x8 desky','M2x8 zur Platinenbefestigung'],sideIRPlug:['3芯コネクター','Three-wire connector','Třívodičový konektor','Dreipoliger Stecker'],sideIRPanel:['右パネル','Right panel','Pravý panel','Rechtes Blech'],sideIRHandle:['右ハンドル','Right handle','Pravá rukojeť','Rechter Griff'],sideIRInputTube:['短い入力PTFE・45 mm','Short input PTFE ·45 mm','Krátká vstupní PTFE ·45 mm','Kurzer Eingangs-PTFE ·45 mm'],sideIRInputCollet:['入力側コレット','Input collet','Vstupní kleština','Eingangsklemmring'],sideIRTubeCollet:['長いPTFEのコレット','Long PTFE collet','Kleština dlouhé PTFE','Klemmring des langen PTFE'],sideIRFreeLead:['センサーの3本の配線','Three sensor wires','Tři vodiče senzoru','Drei Sensorleitungen'],sideIRMainPTFE:['長いPTFE・710 mm','Long PTFE ·710 mm','Dlouhá PTFE ·710 mm','Langer PTFE ·710 mm']
};
const components={Body:['センサー本体','Sensor housing','Pouzdro senzoru','Sensorgehäuse'],Cover:['センサーカバー','Sensor cover','Kryt senzoru','Sensorabdeckung'],Lever:['センサーレバー','Sensor lever','Páčka senzoru','Sensorhebel'],Switch:['機械式スイッチ','Mechanical switch','Mechanický přepínač','Mechanischer Schalter'],Ball:['センサーボール','Sensor ball','Kulička senzoru','Sensorkugel'],LeverMagnet:['レバーの磁石','Lever magnet','Magnet páčky','Hebelmagnet'],SwitchMagnet:['スイッチの磁石','Switch magnet','Magnet přepínače','Schaltermagnet'],LeverScrew:['レバーの支点ねじ','Lever pivot screw','Šroub čepu páčky','Hebelachsschraube'],LeverWasher:['レバーのワッシャー','Lever washer','Podložka páčky','Hebelscheibe']};
export function sideIRPartNames(ref,length){
 if(names[ref])return names[ref];
 if(ref==='sideIRHandleRear'||ref==='sideIRHandleFront'){const label=ref.endsWith('Rear')?['後ろのハンドルねじ','Rear handle screw','Zadní šroub rukojeti','Hintere Griffschraube']:['前のハンドルねじ','Front handle screw','Přední šroub rukojeti','Vordere Griffschraube'];return label.map(s=>s+' ·M3x'+length+'rT');}
 let m=ref.match(/^sideIR(?:R1|Plus)(.+)$/);if(m){if(components[m[1]])return components[m[1]];let n=m[1].match(/^(CoverScrew|MountNut)([01])$/);if(n){const i=+n[2]+1;return n[1]==='CoverScrew'?['カバーねじ'+i,'Cover screw '+i,'Šroub krytu '+i,'Deckelschraube '+i]:['取付け用M3角ナット'+i,'Mounting M3 square nut '+i,'Montážní čtvercová matice M3 '+i,'M3-Vierkantmutter '+i];}}
 m=ref.match(/^sideIRRivet(Pin|Sleeve)(\d+)$/);if(m){const i=+m[2]+1;return m[1]==='Pin'?['リベット'+i+'の中央ピン','Rivet '+i+' centre pin','Středový kolík nýtu '+i,'Mittelstift von Niet '+i]:['リベット'+i+'の筒','Rivet '+i+' sleeve','Pouzdro nýtu '+i,'Hülse von Niet '+i];}
 throw Error('Missing side IR part name: '+ref);
}
